namespace RaceDay.API.Models;
public class User { public int UserId { get; set; } public int RoleId { get; set; } public Role? Role { get; set; } public string Email { get; set; } = string.Empty; public string PasswordHash { get; set; } = string.Empty; public string FirstName { get; set; } = string.Empty; public string LastName { get; set; } = string.Empty; public string? Phone { get; set; } public string? ProfilePictureUrl { get; set; } public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public ICollection<Event> OrganisedEvents { get; set; } = new List<Event>(); public ICollection<Enrolment> Enrolments { get; set; } = new List<Enrolment>(); }